style.css:
/* ? Videoların etrafına siyah glow efekti */
ytd-video-renderer, ytd-grid-video-renderer, ytd-rich-item-renderer {
  background-color: rgba(0, 0, 0, 0.2) !important;
  border-radius: 12px;
  box-shadow: 0 0 20px rgba(0, 0, 0, 0.7), 0 0 40px rgba(0, 0, 0, 0.5) !important;
  backdrop-filter: blur(4px);
  padding: 8px;
}

/* ? Butonlara blur arka plan efekti */
button, yt-icon-button, paper-button, ytd-subscribe-button-renderer {
  background: rgba(0, 0, 0, 0.3) !important;
  backdrop-filter: blur(6px) !important;
  border-radius: 8px !important;
  color: #e0f7ff !important;
  text-shadow: 0 0 8px #e0f7ff, 0 0 12px #66ccff !important;
  box-shadow: 0 0 8px #66ccff, 0 0 16px #ffffff !important;
  transition: all 0.2s ease-in-out;
  border: none !important;
}

/* Buton hover efekti aynı kalsın ama blur da kalsın */
button:hover, yt-icon-button:hover, paper-button:hover, ytd-subscribe-button-renderer:hover {
  box-shadow: 0 0 12px #66ccff, 0 0 20px #ffffff !important;
  transform: scale(1.05);
}

/* ? Abone ol butonu da uyumlu olsun */
ytd-subscribe-button-renderer paper-button {
  background: rgba(0, 0, 0, 0.3) !important;
  backdrop-filter: blur(6px) !important;
  border-radius: 8px;
  font-weight: bold;
}
